def route(chunks):
    thinking=''; answer=''; live=False
    for text in chunks:
        if not live:
            printed=text if thinking or not text.startswith(' ') else text[1:]
            thinking+=printed
            if '</think>' in thinking: live=True
        else: answer+=text
    return answer.strip()
for chunks in [['reason</think>', 'Answer'], ['reason</think>Answer'], ['reason</thi','nk>Answer']]:
    print(repr(chunks), 'history=', repr(route(chunks)))
def suffix(old,new):
    p=0
    for x,y in zip(old,new):
        if x!=y: break
        p+=1
    return p,len(old)-p,len(new)-p
print('prefix/old_suffix/new_suffix',suffix(['a','b',''],['a','bc','']))

